/**
 * Tooltip HTML for fetiche panel berry chips and feed buttons.
 */

import { escapeHtml } from '../../formatters.ts';
import {
    formatFeticheBerryStatHintHtml,
    hasFeticheBerryStatHint,
    type FeticheBerryStatEffect,
} from '../../constants/balance/feticheBerries.ts';
import type { FeticheBerryFeedSnapshot } from './feticheSnapshot.ts';
import type { FeticheTaste } from './feticheLogic.ts';

export type FeticheBerryTooltipUi = {
    tasteLoved: string;
    tasteLiked: string;
    tasteNeutral: string;
    tasteDisliked: string;
    tasteHated: string;
};

const TASTE_ICON: Record<FeticheTaste, string> = {
    loved: '❤️',
    liked: '🙂',
    neutral: '😐',
    disliked: '😕',
    hated: '🤢',
};

export function feticheTasteLabel(taste: FeticheTaste, ui: FeticheBerryTooltipUi): string {
    const labels: Record<FeticheTaste, string> = {
        loved: ui.tasteLoved,
        liked: ui.tasteLiked,
        neutral: ui.tasteNeutral,
        disliked: ui.tasteDisliked,
        hated: ui.tasteHated,
    };
    return labels[taste];
}

export type FeticheBerryTooltipOpts = {
    showQty?: boolean;
};

function appendStatHintLine(parts: string[], statEffect: FeticheBerryStatEffect | null | undefined): void {
    if (!hasFeticheBerryStatHint(statEffect)) return;
    parts.push(formatFeticheBerryStatHintHtml(statEffect!));
}

export function buildFeticheBerryTooltipContent(
    berry: Pick<
        FeticheBerryFeedSnapshot,
        'name' | 'taste' | 'tasteIcon' | 'description' | 'qty' | 'statEffect'
    >,
    ui: FeticheBerryTooltipUi,
    opts?: FeticheBerryTooltipOpts,
): { title: string; body: string } {
    const tasteLabel = feticheTasteLabel(berry.taste, ui);
    const parts: string[] = [
        `${escapeHtml(berry.tasteIcon)} ${escapeHtml(tasteLabel)}`,
    ];
    appendStatHintLine(parts, berry.statEffect);
    if (berry.description) {
        parts.push(escapeHtml(berry.description));
    }
    if (opts?.showQty) {
        parts.push(`×${Math.max(0, Math.floor(Number(berry.qty) || 0))}`);
    }
    return {
        title: escapeHtml(berry.name),
        body: parts.join('<br>'),
    };
}

export type BerryTreeBerryTooltipEntry = {
    name: string;
    feticheTaste: string | null;
    feticheStatEffect: FeticheBerryStatEffect | null;
    description?: string | null;
};

export function buildBerryTreeBerryTooltipContent(
    entry: BerryTreeBerryTooltipEntry,
    ui: FeticheBerryTooltipUi,
): { title: string; body: string } | null {
    if (!entry.feticheTaste) return null;
    const taste = entry.feticheTaste as FeticheTaste;
    const tasteLabel = feticheTasteLabel(taste, ui);
    const parts: string[] = [
        `${escapeHtml(TASTE_ICON[taste])} ${escapeHtml(tasteLabel)}`,
    ];
    appendStatHintLine(parts, entry.feticheStatEffect);
    if (entry.description) {
        parts.push(escapeHtml(entry.description));
    }
    return {
        title: escapeHtml(entry.name),
        body: parts.join('<br>'),
    };
}
